// CSD_RATIONALE_BEGIN
// Root cause of attempts 73-74 regression (40.8% → 10.2%):
// Analysis: The regression was NOT caused by switching from `next == "<<"` to
// `RenderedEndsWith` (those should behave identically for Qwen2.5 since "<<"
// is a single token). The regression was caused by:
//   1. Over-specified, complex guidance in attempts 73-74 confuses the model.
//   2. The `minExprLen=3` restriction in attempt 74 changes closing behavior.
//
// Fix: Return to the EXACT structure of the best attempt (40.8%) with minimal
// targeted changes:
//   1. Replace `next == "<<"` with `RenderedEndsWith(generated, "<<")` as required.
//   2. Use short, clear guidance (close to best-attempt original) but add ONE
//      key instruction: never split a single computation across multiple spans
//      (write <<a + b>> not <<a>> + <<b>>). This directly addresses the main
//      failure modes in the rollouts without over-constraining.
//   3. Remove the `minExprLen` restriction; let parser decide completeness.
//   4. Keep same budget-pressure logic (OpenConstrainedSpan at ≤4 steps,
//      CloseSpanWithinBudget at ≤3 steps).
//
// Evidence: The best attempt got 40.8% with this exact loop structure. The
// rollout failures show splitting (`<<n - n>>*<<p1 + k>>*<<p2>>`) as the
// dominant failure mode, addressed by guidance without structural change.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span, RenderedEndsWith triggers → EnterObservedConstrainedSpan:
//     Sets currentConstrainedOut := []. parser.IsValidPrefix([]) holds by
//     method precondition `parser.IsValidPrefix([])`. ✓
//   Outside-span, OpenConstrainedSpan (budget pressure):
//     Sets insideConstrainedOut := true, currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by precondition. ✓
//   Outside-span, no trigger: insideConstrainedOut stays false; vacuously true. ✓
//   Inside-span, CloseConstrainedSpan: Sets insideConstrainedOut := false;
//     implication vacuously true; currentConstrainedOut := [] by postcondition. ✓
//   Inside-span, CloseSpanWithinBudget: Helper postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//   Inside-span, AdaptiveConstrainedStep + AppendConstrainedToken:
//     AdaptiveConstrainedStep hard-masks to parser-valid next tokens or EOS.
//     AppendConstrainedToken's postcondition guarantees
//     parser.IsValidPrefix(currentConstrainedOut + [next]) when next is valid. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//   Init: steps = 0; |generated| = |generatedPrefix|. ✓
//   Outside-span, OpenConstrainedSpan: steps += 1; generated grows by 1 ("<<");
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps. ✓
//   Outside-span, UnconstrainedStep (EOS or non-EOS): steps += 1; generated
//     grows by at most 1 token; bound preserved. ✓
//   Inside-span, CloseConstrainedSpan: steps += 1; generated grows by at most 1
//     token (">>"); bound preserved. ✓
//   Inside-span, CloseSpanWithinBudget: closeBudget = maxSteps - steps; helper
//     postcondition gives |cg| <= |generated| + closeBudget. By inductive
//     hypothesis |generated| <= |generatedPrefix| + steps_old, so
//     |cg| <= |generatedPrefix| + maxSteps. After steps := maxSteps: ✓
//   Inside-span, AdaptiveConstrainedStep (non-EOS): steps += 1;
//     AppendConstrainedToken adds exactly 1 token; bound preserved. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap every computed expression inside << >>. Each << >> must contain ONE complete expression—never split a single computation across multiple spans (write <<a + b>> not <<a>> + <<b>>). The final << >> is the complete answer expression combining all relevant terms.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if maxSteps - steps <= 4 && steps > 0 {
      // Budget pressure: force open a constrained span for the final answer.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if RenderedEndsWith(generated, "<<") {
          var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := eg;
          insideConstrainedOut := ei;
          currentConstrainedOut := ec;
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Expression is complete: close the span.
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Near budget end: use CloseSpanWithinBudget to finish gracefully.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation: advance one parser-valid token.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

